CREATE TABLE invoices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), restaurant_id uuid NOT NULL REFERENCES restaurants(id), table_session_id uuid, subtotal_paise integer NOT NULL CHECK(subtotal_paise>=0), discount_paise integer NOT NULL DEFAULT 0 CHECK(discount_paise>=0), tax_paise integer NOT NULL DEFAULT 0 CHECK(tax_paise>=0), total_paise integer NOT NULL CHECK(total_paise>=0), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(restaurant_id,id), FOREIGN KEY(restaurant_id,table_session_id) REFERENCES table_sessions(restaurant_id,id), CHECK(total_paise=subtotal_paise-discount_paise+tax_paise));
CREATE UNIQUE INDEX invoice_table_once ON invoices(restaurant_id,table_session_id) WHERE table_session_id IS NOT NULL;
CREATE TABLE invoice_orders (restaurant_id uuid NOT NULL, invoice_id uuid NOT NULL, order_id uuid NOT NULL, PRIMARY KEY(restaurant_id,order_id), FOREIGN KEY(restaurant_id,invoice_id) REFERENCES invoices(restaurant_id,id), FOREIGN KEY(restaurant_id,order_id) REFERENCES orders(restaurant_id,id));
CREATE TYPE demo_payment_method AS ENUM ('cash','upi','card');
CREATE TABLE payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), restaurant_id uuid NOT NULL, invoice_id uuid NOT NULL, method demo_payment_method NOT NULL, amount_paise integer NOT NULL CHECK(amount_paise>=0), recorded_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(restaurant_id,invoice_id), FOREIGN KEY(restaurant_id,invoice_id) REFERENCES invoices(restaurant_id,id));
